interface UserPreferences {
  theme: string;
  language: string;
  notifications: boolean;
  timestamp: string;
}

async function getUserPreferences(): Promise<UserPreferences> {
  // Fetch user preferences with cache: 'no-store' to ensure fresh data on each request
  const res = await fetch('http://localhost:3000/api/user/preferences', {
    cache: 'no-store',
  });

  if (!res.ok) {
    throw new Error('Failed to fetch user preferences');
  }

  return res.json();
}

export default async function UserDashboard() {
  const preferences = await getUserPreferences();

  return (
    <div>
      <h2>User Dashboard</h2>
      <div style={{ padding: '1rem', border: '1px solid #ccc', borderRadius: '8px' }}>
        <h3>User Preferences (Dynamic Data)</h3>
        <ul>
          <li><strong>Theme:</strong> {preferences.theme}</li>
          <li><strong>Language:</strong> {preferences.language}</li>
          <li><strong>Notifications:</strong> {preferences.notifications ? 'Enabled' : 'Disabled'}</li>
          <li><strong>Last Updated:</strong> {new Date(preferences.timestamp).toLocaleString()}</li>
        </ul>
        <p style={{ fontSize: '0.9rem', color: '#666', marginTop: '1rem' }}>
          Refresh the page to see updated data (fetched fresh on each request)
        </p>
      </div>
    </div>
  );
}

